  "text": "import numpy as np\nfrom sklearn.datasets import make_classification\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.tree import DecisionTreeClassifier\nfrom sklearn.ensemble import BaggingClassifier, RandomForestClassifier, ExtraTreesClassifier\n\nX, y = make_classification(n_samples=4000, n_features=20, n_informative=8,\n                           n_redundant=4, flip_y=0.05, random_state=0)\nX_tr, X_te, y_tr, y_te = train_test_split(X, y, test_size=0.5, random_state=0)\n\nmodels = {\n    'одно дерево': DecisionTreeClassifier(random_state=0),\n    'бэггинг 200 деревьев': BaggingClassifier(DecisionTreeClassifier(), n_estimators=200,\n                                              oob_score=True, random_state=0, n_jobs=-1),\n    'случайный лес 200': RandomForestClassifier(n_estimators=200, oob_score=True,\n                                                random_state=0, n_jobs=-1),\n    'extra trees 200': ExtraTreesClassifier(n_estimators=200, random_state=0, n_jobs=-1),\n}\nfor name, m in models.items():\n    m.fit(X_tr, y_tr)\n    oob = f'  OOB: {m.oob_score_:.3f}' if hasattr(m, 'oob_score_') else ''\n    print(f'{name:22s} train: {m.score(X_tr, y_tr):.3f}  test: {m.score(X_te, y_te):.3f}{oob}')\n\n# корреляция прогнозов отдельных деревьев: у леса она ниже, чем у бэггинга\ndef mean_corr(ensemble):\n    P = np.array([t.predict_proba(X_te)[:, 1] for t in ensemble.estimators_[:50]])\n    C = np.corrcoef(P)\n    return C[np.triu_indices_from(C, 1)].mean()\n\nprint('средняя корреляция деревьев: бэггинг', round(mean_corr(models['бэггинг 200 деревьев']), 3),\n      ' лес', round(mean_corr(models['случайный лес 200']), 3))",
