  "text": "import time\nimport numpy as np\nfrom sklearn.datasets import make_classification\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.metrics import roc_auc_score\nfrom sklearn.ensemble import GradientBoostingClassifier, HistGradientBoostingClassifier\nimport xgboost as xgb\nimport lightgbm as lgb\nfrom catboost import CatBoostClassifier\n\nX, y = make_classification(n_samples=60_000, n_features=30, n_informative=12,\n                           n_redundant=6, flip_y=0.05, class_sep=0.8, random_state=0)\nX_tr, X_te, y_tr, y_te = train_test_split(X, y, test_size=0.3, random_state=0)\nX_tr, X_val, y_tr, y_val = train_test_split(X_tr, y_tr, test_size=0.2, random_state=0)\n\nmodels = {\n    'sklearn GradientBoosting': GradientBoostingClassifier(n_estimators=300, learning_rate=0.1,\n                                                           max_depth=4, random_state=0),\n    'sklearn HistGradientBoosting': HistGradientBoostingClassifier(max_iter=1000, learning_rate=0.1,\n                                                                   early_stopping=True, random_state=0),\n    'XGBoost': xgb.XGBClassifier(n_estimators=1000, learning_rate=0.1, max_depth=6,\n                                 tree_method='hist', early_stopping_rounds=50,\n                                 eval_metric='logloss', random_state=0, n_jobs=-1),\n    'LightGBM': lgb.LGBMClassifier(n_estimators=1000, learning_rate=0.1, num_leaves=31,\n                                   random_state=0, verbose=-1, n_jobs=-1),\n    'CatBoost': CatBoostClassifier(iterations=1000, learning_rate=0.1, depth=6,\n                                   early_stopping_rounds=50, random_seed=0, verbose=0),\n}\nfit_kw = {\n    'XGBoost': dict(eval_set=[(X_val, y_val)], verbose=False),\n    'LightGBM': dict(eval_X=X_val, eval_y=y_val, callbacks=[lgb.early_stopping(50, verbose=False)]),\n    'CatBoost': dict(eval_set=(X_val, y_val)),\n}\nfor name, m in models.items():\n    t = time.perf_counter()\n    m.fit(X_tr, y_tr, **fit_kw.get(name, {}))\n    sec = time.perf_counter() - t\n    auc = roc_auc_score(y_te, m.predict_proba(X_te)[:, 1])\n    trees = {'XGBoost': lambda: m.best_iteration + 1, 'LightGBM': lambda: m.best_iteration_,\n             'CatBoost': lambda: m.get_best_iteration() + 1,\n             'sklearn HistGradientBoosting': lambda: m.n_iter_}.get(name, lambda: 300)()\n    print(f'{name:30s} ROC-AUC: {auc:.4f}  деревьев: {trees:4d}  время: {sec:5.1f} с')",
