  "text": "import numpy as np\nimport pandas as pd\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.metrics import roc_auc_score\nimport lightgbm as lgb\nfrom catboost import CatBoostClassifier\n\nrng = np.random.default_rng(0)\nn = 30_000\ncity = rng.integers(0, 500, size=n)               # 500 городов, у каждого свой «уровень»\ncity_effect = rng.normal(0, 1, size=500)\nage = rng.uniform(18, 70, size=n)\nincome = rng.lognormal(10, 0.5, size=n)\nlogit = city_effect[city] + 0.04 * (age - 40) + 0.5 * np.log(income / 22_000)\ny = (rng.uniform(size=n) < 1 / (1 + np.exp(-logit))).astype(int)\n\ndf = pd.DataFrame({'city': 'c' + pd.Series(city).astype(str), 'age': age, 'income': income})\nX_tr, X_te, y_tr, y_te = train_test_split(df, y, test_size=0.3, random_state=0)\n\n# 1) наивный target encoding: среднее таргета по городу, посчитанное на всём train\nmeans = pd.Series(y_tr, index=X_tr.index).groupby(X_tr['city']).mean()\nenc_tr = X_tr.assign(city=X_tr['city'].map(means))\nenc_te = X_te.assign(city=X_te['city'].map(means).fillna(y_tr.mean()))\nm1 = lgb.LGBMClassifier(n_estimators=300, learning_rate=0.05, verbose=-1, random_state=0).fit(enc_tr, y_tr)\nprint(f'наивный target encoding: train AUC {roc_auc_score(y_tr, m1.predict_proba(enc_tr)[:, 1]):.3f}'\n      f'  test AUC {roc_auc_score(y_te, m1.predict_proba(enc_te)[:, 1]):.3f}')\n\n# 2) LightGBM со встроенной поддержкой категорий\ncat_tr = X_tr.astype({'city': 'category'})\ncat_te = X_te.astype({'city': pd.CategoricalDtype(cat_tr['city'].cat.categories)})\nm2 = lgb.LGBMClassifier(n_estimators=300, learning_rate=0.05, verbose=-1, random_state=0).fit(cat_tr, y_tr)\nprint(f'LightGBM, category:      train AUC {roc_auc_score(y_tr, m2.predict_proba(cat_tr)[:, 1]):.3f}'\n      f'  test AUC {roc_auc_score(y_te, m2.predict_proba(cat_te)[:, 1]):.3f}')\n\n# 3) CatBoost: строки передаются как есть, кодирование — ordered target statistics\nm3 = CatBoostClassifier(iterations=300, learning_rate=0.05, depth=6, cat_features=['city'],\n                        random_seed=0, verbose=0).fit(X_tr, y_tr)\nprint(f'CatBoost, cat_features:  train AUC {roc_auc_score(y_tr, m3.predict_proba(X_tr)[:, 1]):.3f}'\n      f'  test AUC {roc_auc_score(y_te, m3.predict_proba(X_te)[:, 1]):.3f}')",
