 "c8": {
  "text": "import numpy as np\nfrom sklearn.datasets import make_classification\nfrom sklearn.model_selection import train_test_split, cross_val_predict, StratifiedKFold\nfrom sklearn.metrics import roc_auc_score\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.neighbors import KNeighborsClassifier\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.svm import SVC\nfrom sklearn.calibration import CalibratedClassifierCV\nfrom sklearn.ensemble import RandomForestClassifier, StackingClassifier\nimport lightgbm as lgb\n\nX, y = make_classification(n_samples=6000, n_features=20, n_informative=10, n_redundant=4,\n                           flip_y=0.05, class_sep=0.7, random_state=1)\nX_tr, X_te, y_tr, y_te = train_test_split(X, y, test_size=0.4, random_state=0)\n\nbase = [\n    ('logreg', make_pipeline(StandardScaler(), LogisticRegression(max_iter=1000))),\n    ('knn', make_pipeline(StandardScaler(), KNeighborsClassifier(n_neighbors=25))),\n    ('svm', make_pipeline(StandardScaler(), CalibratedClassifierCV(SVC(), ensemble=False))),\n    ('rf', RandomForestClassifier(n_estimators=300, random_state=0, n_jobs=-1)),\n    ('lgbm', lgb.LGBMClassifier(n_estimators=300, learning_rate=0.05, verbose=-1, random_state=0)),\n]\nfor name, m in base:\n    m.fit(X_tr, y_tr)\n    print(f'{name:8s} test AUC: {roc_auc_score(y_te, m.predict_proba(X_te)[:, 1]):.4f}')\n\n# простое усреднение вероятностей\navg = np.mean([m.predict_proba(X_te)[:, 1] for _, m in base], axis=0)\nprint(f'{\"среднее\":8s} test AUC: {roc_auc_score(y_te, avg):.4f}')\n\n# стекинг: метапризнаки — out-of-fold прогнозы базовых моделей, метамодель — логрег\nstack = StackingClassifier(estimators=base, final_estimator=LogisticRegression(),\n                           cv=StratifiedKFold(5, shuffle=True, random_state=0),\n                           stack_method='predict_proba', n_jobs=-1).fit(X_tr, y_tr)\nprint(f'{\"стекинг\":8s} test AUC: {roc_auc_score(y_te, stack.predict_proba(X_te)[:, 1]):.4f}')\nprint('веса метамодели:', dict(zip([n for n, _ in base], stack.final_estimator_.coef_[0].round(2).tolist())))\n\n# блендинг: базовые модели учатся на 80 % train, метамодель — на отложенных 20 %\nX_a, X_b, y_a, y_b = train_test_split(X_tr, y_tr, test_size=0.2, random_state=0)\nmeta_b = np.column_stack([m.fit(X_a, y_a).predict_proba(X_b)[:, 1] for _, m in base])\nmeta_te = np.column_stack([m.predict_proba(X_te)[:, 1] for _, m in base])\nblender = LogisticRegression().fit(meta_b, y_b)\nprint(f'{\"блендинг\":8s} test AUC: {roc_auc_score(y_te, blender.predict_proba(meta_te)[:, 1]):.4f}')\n\n# ошибка: метамодель на прогнозах, сделанных на тех же данных, на которых учились базовые модели\nleak_tr = np.column_stack([m.fit(X_tr, y_tr).predict_proba(X_tr)[:, 1] for _, m in base])\nleak = LogisticRegression().fit(leak_tr, y_tr)\nmeta_te = np.column_stack([m.predict_proba(X_te)[:, 1] for _, m in base])\nprint(f'{\"утечка\":8s} test AUC: {roc_auc_score(y_te, leak.predict_proba(meta_te)[:, 1]):.4f}')\nprint('веса при утечке:', dict(zip([n for n, _ in base], leak.coef_[0].round(2).tolist())))",
  "out": "logreg   test AUC: 0.8408\nknn      test AUC: 0.9436\nsvm      test AUC: 0.9520\nrf       test AUC: 0.9489\nlgbm     test AUC: 0.9529\nсреднее  test AUC: 0.9506\nстекинг  test AUC: 0.9588\nвеса метамодели: {'logreg': -2.14, 'knn': 2.25, 'svm': 2.82, 'rf': 1.17, 'lgbm': 2.88}\nблендинг test AUC: 0.9569\nутечка   test AUC: 0.9548\nвеса при утечке: {'logreg': -0.52, 'knn': 0.18, 'svm': 0.92, 'rf': 5.61, 'lgbm': 7.04}"
 },
