  "text": "import numpy as np\nfrom sklearn.datasets import make_classification\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.metrics import roc_auc_score\nimport lightgbm as lgb\n\nX, y = make_classification(n_samples=60_000, n_features=30, n_informative=12,\n                           n_redundant=6, flip_y=0.05, class_sep=0.8, random_state=0)\nX_tr, X_te, y_tr, y_te = train_test_split(X, y, test_size=0.3, random_state=0)\nX_tr, X_val, y_tr, y_val = train_test_split(X_tr, y_tr, test_size=0.2, random_state=0)\n\nfor lr in [0.3, 0.1, 0.03]:\n    m = lgb.LGBMClassifier(n_estimators=5000, learning_rate=lr, num_leaves=31,\n                           subsample=0.8, subsample_freq=1, colsample_bytree=0.8,\n                           random_state=0, verbose=-1)\n    m.fit(X_tr, y_tr, eval_X=X_val, eval_y=y_val, eval_metric='auc',\n          callbacks=[lgb.early_stopping(100, verbose=False)])\n    auc = roc_auc_score(y_te, m.predict_proba(X_te)[:, 1])\n    print(f'learning_rate={lr:<5} лучшая итерация: {m.best_iteration_:5d}  test AUC: {auc:.4f}')",
