const plain = text => ({ t: 'example', label: 'Простыми словами', text })
const code = k => ({ t: 'code', text: CODE[k].text, out: CODE[k].out })

// Карта решений на «лунах»: строка из 0 и 1 по сетке (внешний цикл — x₁, внутренний — x₂)
const mapCells = bits => {
  const [x0, x1, y0, y1] = MOONS.box, s = MOONS.step
  const nx = Math.round((x1 - x0) / s), ny = Math.round((y1 - y0) / s)
  const out = []
  for (let i = 0; i < nx; i++) for (let j = 0; j < ny; j++) out.push([x0 + s / 2 + i * s, y0 + s / 2 + j * s, +bits[i * ny + j]])
  return out
}
const moonsPlot = (key, caption) => ({ t: 'plot', caption, equal: true, axesAtZero: false, legend: false,
  x: { min: MOONS.box[0], max: MOONS.box[1], step: 0.5, label: 'x₁' }, y: { min: MOONS.box[2], max: MOONS.box[3], step: 0.5, label: 'x₂' },
  series: [
    { type: 'cells', size: MOONS.step, points: mapCells(MOONS.maps[key]), colors: ['blue', 'orange'], opacity: 0.22 },
    { type: 'scatter', points: MOONS.c0, color: 'blue', r: 3.4, opacity: 1, stroke: '#0B0B0E' },
    { type: 'scatter', points: MOONS.c1, color: 'orange', r: 3.4, opacity: 1, stroke: '#0B0B0E' },
  ] })

